-- =============================================================================
-- SIKEU - 02. Bagan akun standar (Chart of Accounts) rumah sakit
-- Jalankan sebagai user SIKEU, SESUDAH 01_struktur_pembukuan.sql. DIBUAT OTOMATIS oleh
-- database/sql/tools/bagan_akun.php - ubah bagan di sana lalu jalankan ulang generatornya.
--
-- ACUAN
--   * SAK EP (Standar Akuntansi Keuangan Entitas Privat, berlaku 1 Jan 2025, pengganti SAK ETAP):
--     penyajian aset/liabilitas lancar vs tidak lancar, istilah "liabilitas", akun kontra
--     (akumulasi penyusutan, cadangan kerugian piutang), pendapatan diukur sebesar imbalan yang
--     berhak diterima (selisih tarif INA-CBG/iDRG = penyesuaian pendapatan, bukan laba/rugi lain),
--     diskon pembelian mengurangi biaya perolehan persediaan, imbalan kerja, pajak kini & tangguhan.
--   * Pola pedoman akuntansi rumah sakit: pendapatan per instalasi pelayanan (RJ, Klinik, UGD, RI,
--     Kamar Operasi, Farmasi), beban pokok pelayanan (HPP obat, BMHP, jasa medis) dipisah dari
--     beban umum & administrasi -> laporan laba rugi bisa menampilkan LABA KOTOR PELAYANAN.
--   * Bila badan hukumnya YAYASAN (nirlaba), penyajian memakai ISAK 35: cukup ganti nama kelompok 3
--     menjadi ASET NETO dan rincian 3.1.xx menjadi "tanpa/dengan pembatasan"; akun lain tetap.
--
-- KODE  K.S.GG.DDD   K kelompok, S subkelompok, GG golongan, DDD rincian. Contoh 4.1.04.002.
--   Tingkat 1-3 = Header (H, tidak boleh dijurnal), tingkat 4 = Detail (D).
--   Rincian 9xx = akun kontra / pengurang di golongannya.
--   1.1.09.001 Akun Penampung: tempat sementara pos yang belum jelas; WAJIB nol saat periode dikunci.
--
-- Bagian: A periksa - B kelompok akun - C bagan akun - D verifikasi - E rollback
-- =============================================================================
SET DEFINE OFF

-- A. PERIKSA - hasil harus 0 baris akun. Bila sudah terisi, lihat bagian E dulu.
SELECT COUNT(*) AS jumlah_akun FROM sikeumst_akuns;

-- B. KELOMPOK AKUN (9 kelompok, susunan laporan SAK EP)
MERGE INTO sikeumst_akun_kelompoks t USING (SELECT '1' id FROM dual) s ON (t.kelompok_id = s.id)
  WHEN MATCHED THEN UPDATE SET t.nama = 'ASET', t.saldo_normal = 'D', t.jenis_laporan = 'N', t.urut = 1
  WHEN NOT MATCHED THEN INSERT (kelompok_id, nama, saldo_normal, jenis_laporan, urut) VALUES ('1', 'ASET', 'D', 'N', 1);
MERGE INTO sikeumst_akun_kelompoks t USING (SELECT '2' id FROM dual) s ON (t.kelompok_id = s.id)
  WHEN MATCHED THEN UPDATE SET t.nama = 'LIABILITAS', t.saldo_normal = 'K', t.jenis_laporan = 'N', t.urut = 2
  WHEN NOT MATCHED THEN INSERT (kelompok_id, nama, saldo_normal, jenis_laporan, urut) VALUES ('2', 'LIABILITAS', 'K', 'N', 2);
MERGE INTO sikeumst_akun_kelompoks t USING (SELECT '3' id FROM dual) s ON (t.kelompok_id = s.id)
  WHEN MATCHED THEN UPDATE SET t.nama = 'EKUITAS', t.saldo_normal = 'K', t.jenis_laporan = 'N', t.urut = 3
  WHEN NOT MATCHED THEN INSERT (kelompok_id, nama, saldo_normal, jenis_laporan, urut) VALUES ('3', 'EKUITAS', 'K', 'N', 3);
MERGE INTO sikeumst_akun_kelompoks t USING (SELECT '4' id FROM dual) s ON (t.kelompok_id = s.id)
  WHEN MATCHED THEN UPDATE SET t.nama = 'PENDAPATAN USAHA', t.saldo_normal = 'K', t.jenis_laporan = 'L', t.urut = 4
  WHEN NOT MATCHED THEN INSERT (kelompok_id, nama, saldo_normal, jenis_laporan, urut) VALUES ('4', 'PENDAPATAN USAHA', 'K', 'L', 4);
MERGE INTO sikeumst_akun_kelompoks t USING (SELECT '5' id FROM dual) s ON (t.kelompok_id = s.id)
  WHEN MATCHED THEN UPDATE SET t.nama = 'BEBAN POKOK PELAYANAN', t.saldo_normal = 'D', t.jenis_laporan = 'L', t.urut = 5
  WHEN NOT MATCHED THEN INSERT (kelompok_id, nama, saldo_normal, jenis_laporan, urut) VALUES ('5', 'BEBAN POKOK PELAYANAN', 'D', 'L', 5);
MERGE INTO sikeumst_akun_kelompoks t USING (SELECT '6' id FROM dual) s ON (t.kelompok_id = s.id)
  WHEN MATCHED THEN UPDATE SET t.nama = 'BEBAN USAHA', t.saldo_normal = 'D', t.jenis_laporan = 'L', t.urut = 6
  WHEN NOT MATCHED THEN INSERT (kelompok_id, nama, saldo_normal, jenis_laporan, urut) VALUES ('6', 'BEBAN USAHA', 'D', 'L', 6);
MERGE INTO sikeumst_akun_kelompoks t USING (SELECT '7' id FROM dual) s ON (t.kelompok_id = s.id)
  WHEN MATCHED THEN UPDATE SET t.nama = 'PENDAPATAN LAIN-LAIN', t.saldo_normal = 'K', t.jenis_laporan = 'L', t.urut = 7
  WHEN NOT MATCHED THEN INSERT (kelompok_id, nama, saldo_normal, jenis_laporan, urut) VALUES ('7', 'PENDAPATAN LAIN-LAIN', 'K', 'L', 7);
MERGE INTO sikeumst_akun_kelompoks t USING (SELECT '8' id FROM dual) s ON (t.kelompok_id = s.id)
  WHEN MATCHED THEN UPDATE SET t.nama = 'BEBAN LAIN-LAIN', t.saldo_normal = 'D', t.jenis_laporan = 'L', t.urut = 8
  WHEN NOT MATCHED THEN INSERT (kelompok_id, nama, saldo_normal, jenis_laporan, urut) VALUES ('8', 'BEBAN LAIN-LAIN', 'D', 'L', 8);
MERGE INTO sikeumst_akun_kelompoks t USING (SELECT '9' id FROM dual) s ON (t.kelompok_id = s.id)
  WHEN MATCHED THEN UPDATE SET t.nama = 'BEBAN PAJAK PENGHASILAN', t.saldo_normal = 'D', t.jenis_laporan = 'L', t.urut = 9
  WHEN NOT MATCHED THEN INSERT (kelompok_id, nama, saldo_normal, jenis_laporan, urut) VALUES ('9', 'BEBAN PAJAK PENGHASILAN', 'D', 'L', 9);

-- C. BAGAN AKUN (285 akun: 72 header, 213 detail). Induk selalu sebelum anak.

COMMIT;

-- D. VERIFIKASI
--   D1 jumlah per kelompok & tipe - total harus 213 detail
SELECT kelompok_id, tipe, COUNT(*) jumlah FROM sikeumst_akuns GROUP BY kelompok_id, tipe ORDER BY 1, 2;
--   D2 header tanpa anak / detail yang punya anak - harus 0 baris
SELECT a.akun_id, a.tipe FROM sikeumst_akuns a
 WHERE (a.tipe = 'H' AND NOT EXISTS (SELECT 1 FROM sikeumst_akuns c WHERE c.induk_id = a.akun_id))
    OR (a.tipe = 'D' AND EXISTS (SELECT 1 FROM sikeumst_akuns c WHERE c.induk_id = a.akun_id));
--   D3 akun kas/bank
SELECT akun_id, nama FROM sikeumst_akuns WHERE kas_status = '1' ORDER BY akun_id;

-- E. ROLLBACK (hanya bila BELUM ada jurnal; FK menolak bila akun sudah dipakai)
